// One-module-at-a-time Cecil metadata/IL inspection; no game assembly execution.
using System;using System.IO;using System.Linq;using System.Text;using System.Text.Json;using System.Collections.Generic;using System.Security.Cryptography;using System.Globalization;using Mono.Cecil;using Mono.Cecil.Cil;using RR23.MetadataRestoration;
static class CurrentScriptMetadataInventory {
 static void Need(bool b,string s){if(!b)throw new InvalidDataException(s);}static string Sha(string p){using var f=File.OpenRead(p);return Convert.ToHexString(SHA256.HashData(f)).ToLowerInvariant();}static string Part(string s)=>s.Length.ToString(CultureInfo.InvariantCulture)+":"+s;
 static IEnumerable<TypeDefinition> Walk(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var c in Walk(t.NestedTypes))yield return c;}}
 static string Shape(TypeReference t,int depth=0){Need(depth<=32,"TypeSpec depth");if(t is RequiredModifierType||t is OptionalModifierType||t is PinnedType||t is SentinelType||t is FunctionPointerType)throw new InvalidDataException("Unsupported exact TypeSpec "+t.GetType().Name);if(t is GenericParameter p)return(p.Type==GenericParameterType.Method?"M":"V")+p.Position;if(t is ByReferenceType b)return"&"+Shape(b.ElementType,depth+1);if(t is PointerType q)return"*"+Shape(q.ElementType,depth+1);if(t is ArrayType a){if(a.IsVector)return"[]"+Shape(a.ElementType,depth+1);Need(a.Rank>=2&&a.Rank<=32&&a.Dimensions.All(d=>!d.LowerBound.HasValue&&!d.UpperBound.HasValue),"Unsupported array bounds");return"A"+a.Rank+";"+Shape(a.ElementType,depth+1);}if(t is GenericInstanceType g)return"G"+Shape(g.ElementType,depth+1)+"["+string.Concat(g.GenericArguments.Select(x=>Part(Shape(x,depth+1))))+"]";Need(t is not TypeSpecification,"Unhandled TypeSpec");int n=(int)t.MetadataType;if(n>=1&&n<=14||n==22||n==24||n==25||n==28)return"P"+n;Need(t.MetadataType==MetadataType.Class||t.MetadataType==MetadataType.ValueType,"Unsupported named metadata kind");return"T"+(t.IsValueType?"17;":"18;")+Part(CanonicalMetadataSignatures.Assembly(t))+Part(t.FullName);}
 static string Body(MethodDefinition m){if(!m.HasBody)return m.IsAbstract?"abstract_no_IL_by_contract":m.IsPInvokeImpl?"PInvoke_no_IL_by_contract":"extern_or_runtime_or_missing_no_IL";var ins=m.Body.Instructions.Where(i=>i.OpCode.Code!=Code.Nop).ToArray();var c=ins.Select(i=>i.OpCode.Code).ToArray();if(c.Length==0)return"empty_IL_body";if(ins.Any(i=>i.OpCode.Code==Code.Newobj&&i.Operand is MethodReference r&&r.DeclaringType.FullName.EndsWith("AnalysisFailedException",StringComparison.Ordinal)))return"Cpp2IL_analysis_failure_stub";if(c.SequenceEqual(new[]{Code.Ldnull,Code.Throw}))return"throw_null_placeholder_or_unverified_behavior";if(c.SequenceEqual(new[]{Code.Ret}))return"empty_void_body_stub_or_original_trivial_ambiguous";if(c.SequenceEqual(new[]{Code.Ldnull,Code.Ret}))return"null_return_stub_or_original_trivial_ambiguous";if(c.Length<=6&&c.Contains(Code.Initobj)&&c.Last()==Code.Ret)return"default_return_stub_or_original_trivial_ambiguous";if(c.Length==2&&c[1]==Code.Ret&&(ins[0].OpCode.Name.StartsWith("ldc.",StringComparison.Ordinal)||c[0]==Code.Ldstr))return"constant_return_stub_or_original_leaf_ambiguous";return"nonempty_IL_unverified_not_proof_of_original_behavior";}
 static int Main(string[] a){Need(a.Length==2&&!Directory.Exists(a[1]),"input-modules.json fresh-output");Directory.CreateDirectory(a[1]);using var plan=JsonDocument.Parse(File.ReadAllBytes(a[0]));var summary=new List<object>();foreach(var item in plan.RootElement.GetProperty("modules").EnumerateArray()){string path=item.GetProperty("path").GetString(),expected=item.GetProperty("sha256").GetString(),role=item.GetProperty("role").GetString();Need(Sha(path)==expected,"Managed input SHA mismatch");using(var module=ModuleDefinition.ReadModule(path,new ReaderParameters{ReadingMode=ReadingMode.Deferred,ReadSymbols=false,InMemory=false})){string image=module.Assembly.Name.Name+".dll";Need(Path.GetFileName(image)==image,"Unsafe module identity");var tp=Path.Combine(a[1],image+".types.jsonl");var mp=Path.Combine(a[1],image+".methods.jsonl");Need(!File.Exists(tp)&&!File.Exists(mp),"Duplicate current assembly simple identity");int types=0,methods=0,bad=0;var kinds=new Dictionary<string,int>();using var tw=new StreamWriter(tp,false,new UTF8Encoding(false));using var mw=new StreamWriter(mp,false,new UTF8Encoding(false));foreach(var type in Walk(module.Types)){tw.WriteLine(JsonSerializer.Serialize(new{record="type",image,assembly_full_identity=module.Assembly.Name.FullName,role,path,current_cli_token=type.MetadataToken.ToUInt32(),current_cli_token_is_original=false,full_name=type.FullName,flags=(int)type.Attributes,declared_generic_arity=type.GenericParameters.Count,fields=type.Fields.Count,methods=type.Methods.Count,properties=type.Properties.Count,events=type.Events.Count,compiler_generated_marker=type.CustomAttributes.Any(x=>x.AttributeType.FullName=="System.Runtime.CompilerServices.CompilerGeneratedAttribute")}));types++;foreach(var method in type.Methods){string returned=null,error=null;string[] parameters=null;try{returned=Shape(method.ReturnType);parameters=method.Parameters.Select(p=>Shape(p.ParameterType)).ToArray();}catch(Exception e){error=e.GetType().Name+":"+e.Message;bad++;}string body;try{body=Body(method);}catch(Exception e){body="IL_read_error:"+e.GetType().Name;error=(error??"")+"|"+e.Message;}kinds[body]=kinds.TryGetValue(body,out int n)?n+1:1;mw.WriteLine(JsonSerializer.Serialize(new{record="method",image,role,owner=type.FullName,name=method.Name,current_cli_token=method.MetadataToken.ToUInt32(),current_cli_token_is_original=false,flags=(int)method.Attributes,impl_flags=(int)method.ImplAttributes,has_this=method.HasThis,explicit_this=method.ExplicitThis,calling_convention=(int)method.CallingConvention,generic_arity=method.GenericParameters.Count,return_shape=returned,parameters_shape=parameters,shape_error=error,body_kind=body,body_present=method.HasBody,instruction_count=method.HasBody?method.Body.Instructions.Count:0,original_behavior_proven=false}));methods++;}}tw.Flush();mw.Flush();Need(Sha(path)==expected,"Managed file changed during inventory");summary.Add(new{image,assembly_identity=module.Assembly.Name.FullName,path,sha256=expected,role,types,methods,shape_errors=bad,body_kinds=kinds,type_inventory=tp,method_inventory=mp});}GC.Collect();GC.WaitForPendingFinalizers();}File.WriteAllText(Path.Combine(a[1],"report.json"),JsonSerializer.Serialize(new{schema="current-script-metadata-and-ambiguous-IL-body-inventory/v1",modules=summary,game_or_sdk_code_loaded_for_execution=false,project_modified=false,limitations="IL patterns classify stubs/ambiguity only; nonempty bodies and metadata presence do not prove original recovered behavior. Current CLI row tokens are never original native tokens."},new JsonSerializerOptions{WriteIndented=true}));return 0;}
}
